  0x0598: { name: "seedObjectRamShadowField", role: "[seen] copy 32 bytes from a ROM template into one interleaved (stride-2) field of the OBJRAM shadow (0x4021,0x4023,...,0x405f) at screen/formation init", cert: "seen" },
  0x070e: { name: "reloadSequenceDwellTimer", role: "[seen] re-arm the mid-tier sequence dwell timer (0x4009) to 0x50 (80 ticks) after the handler sets the next state", cert: "seen" },
  0x08e5: { name: "clearGateOnPendingRequest", role: "[seen] When request flag 0x420b bit0 is pending, acknowledge it (clear 0x420b) and clear the behavior gate 0x4208 that runGameplayFrameAndAdvanceOnFieldClear/advanceFormationSweepOscillator test.", cert: "seen" },
  0x090b: { name: "loc_090b", role: "[seen] Shared stack epilogue of the enqueueCommandWord path: pop the caller's saved HL and return; no work-RAM effect.", cert: "seen" },
  0x0972: { name: "broadcastToStridedTable", role: "[seen] Broadcast the byte in A across the 9-cell stride-2 work-RAM table at 0x4028 (0x4028,0x402a,...,0x4038).", cert: "seen" },
  0x097d: { name: "setSweepDescending", role: "[seen] Set object sweep-direction flag 0x420d (OBJ_SWEEP_DIRECTION) to 1, switching the oscillator to its decreasing/descending phase; called by advanceFormationSweepOscillator when the swept 0x420e word reaches the upper bound.", cert: "seen" },
