  0x108e: { name: "advanceObjectPathStepAlias", role: "[seen] Object-AI dispatch slot 11 (@0x0cfc): a bare trampoline that forwards unchanged to advanceObjectPathStep (0x0d71, the slot-1 path-walk handler); it performs no work and holds no state of its own.", cert: "seen" },
